export const CHILD_AVATARS = [...BOY_AVATARS, ...GIRL_AVATARS];
export const ADULT_AVATARS = [...PARENT_AVATARS, ...GRANDPARENT_AVATARS];
export const ALL_AVATARS = [...CHILD_AVATARS, ...ADULT_AVATARS];

export function getAvatarsByRole(role?: string): AvatarOption[] {
  if (role === 'child') return CHILD_AVATARS;
  if (role === 'parent') return PARENT_AVATARS;
  return ALL_AVATARS;
}

export function getAvatarById(id: string): AvatarOption | undefined {
  return ALL_AVATARS.find(a => a.id === id);
}

