export function getTaskTemplatesByCategory(cat?: string) {
  if (!cat) return TASK_TEMPLATES;
  return TASK_TEMPLATES.filter(t => t.category === cat);
}

export function getRewardTemplatesByCategory(cat?: string) {
  if (!cat) return REWARD_TEMPLATES;
  return REWARD_TEMPLATES.filter(r => r.category === cat);
}

